-- Reviewed senior batch 028; all images remotely verified.
begin;
do $guard$ declare batch_content jsonb := $senior_content$[{"source_id":6384,"word":"academic","meaning":"學業的；學術的","example":"Her academic interests included history and biology.","example_zh":"她的學術興趣包括歷史與生物。","original_meaning":"學業的；學術的","original_example":"Lena met her academic adviser before choosing next semester's classes.","original_example_zh":"Lena 選下學期的課之前，先和課業指導老師討論。"},{"source_id":6385,"word":"lecture","meaning":"講座；演講","example":"The students attended a lecture about ancient cities.","example_zh":"學生參加一場關於古城的講座。","original_meaning":"講座；演講","original_example":"During the career lecture, I wrote down two questions for the architect.","original_example_zh":"職涯講座進行時，我寫下兩個想問建築師的問題。"},{"source_id":6389,"word":"nutritious","meaning":"營養豐富的","example":"The cook prepared a nutritious lunch for the group.","example_zh":"廚師為團體準備營養豐富的午餐。","original_meaning":"營養豐富的","original_example":"A nutritious breakfast does not need to be expensive or complicated.","original_example_zh":"營養豐富的早餐不一定昂貴或複雜。"},{"source_id":6390,"word":"balanced","meaning":"均衡的；平衡的","example":"The cafeteria offered a balanced meal with several food groups.","example_zh":"餐廳提供包含多類食物的均衡餐點。","original_meaning":"均衡的；平衡的","original_example":"I packed a balanced lunch with rice, vegetables, tofu, and fruit.","original_example_zh":"我準備了包含飯、蔬菜、豆腐和水果的均衡午餐。"},{"source_id":6391,"word":"consume","meaning":"食用；消耗","example":"The hikers planned to consume their packed lunch at the rest stop.","example_zh":"健行者計畫在休息站吃帶來的午餐。","original_meaning":"食用；消耗","original_example":"Athletes should consume enough water before they feel thirsty.","original_example_zh":"運動員應該在感到口渴前補充足夠的水。"},{"source_id":6392,"word":"dietary","meaning":"飲食的","example":"The chef asked about the guests' dietary preferences.","example_zh":"主廚詢問客人的飲食偏好。","original_meaning":"飲食的","original_example":"The camp form asks whether students have any dietary restrictions.","original_example_zh":"營隊表格會詢問學生是否有飲食限制。"},{"source_id":6393,"word":"serving","meaning":"一份食物；服務","example":"She placed a serving of soup in each bowl.","example_zh":"她在每個碗裡盛了一份湯。","original_meaning":"一份食物；服務","original_example":"One serving of the soup was enough because it contained beans and noodles.","original_example_zh":"這碗湯有豆子和麵，一份就很有飽足感。"},{"source_id":6396,"word":"processed","meaning":"加工的","example":"The lesson compared fresh ingredients with processed foods.","example_zh":"課程比較新鮮食材與加工食品。","original_meaning":"加工的","original_example":"We compared a processed snack with nuts and fresh fruit.","original_example_zh":"我們比較了加工零食、堅果和新鮮水果。"},{"source_id":6397,"word":"preserve","meaning":"保存；保護","example":"The museum worked to preserve the old photographs.","example_zh":"博物館努力保存這些老照片。","original_meaning":"保存；保護","original_example":"Grandma freezes extra dumplings to preserve them for busy days.","original_example_zh":"奶奶把多包的水餃冷凍，留到忙碌的日子吃。"},{"source_id":6398,"word":"calorie","meaning":"卡路里；熱量","example":"The dietitian compared the calorie content of several snacks.","example_zh":"營養師比較了幾種點心的熱量。","original_meaning":"卡路里；熱量","original_example":"The coach reminded us that calorie needs differ from person to person.","original_example_zh":"教練提醒我們，每個人需要的熱量並不相同。"},{"source_id":6399,"word":"carbohydrate","meaning":"碳水化合物","example":"The class studied carbohydrate as one component of food.","example_zh":"全班把碳水化合物作為食物的一種成分來研究。","original_meaning":"碳水化合物","original_example":"Rice is the main carbohydrate in our lunch after basketball practice.","original_example_zh":"籃球練習後的午餐中，飯是主要的碳水化合物。"},{"source_id":6400,"word":"vitamin","meaning":"維生素","example":"The food science book included a chapter about each vitamin.","example_zh":"食品科學書有專章介紹每一種維生素。","original_meaning":"維生素","original_example":"The nurse explained which foods provide vitamin C during winter.","original_example_zh":"護理師說明冬天哪些食物能提供維生素 C。"},{"source_id":6403,"word":"vegetarian","meaning":"素食者；素食的","example":"The vegetarian chose a dish made with beans and vegetables.","example_zh":"這位素食者選了一道以豆類和蔬菜做成的料理。","original_meaning":"素食者；素食的","original_example":"The restaurant prepared a vegetarian lunch for three members of our club.","original_example_zh":"餐廳為社團裡三位吃素的成員準備素食午餐。"},{"source_id":6404,"word":"fermented","meaning":"發酵的","example":"The cook added fermented cabbage to the meal.","example_zh":"廚師在餐點裡加上發酵高麗菜。","original_meaning":"發酵的","original_example":"The class learned how fermented foods are made during a visit to the factory.","original_example_zh":"全班參觀工廠時學習發酵食品的製作方式。"},{"source_id":6406,"word":"freshness","meaning":"新鮮度","example":"The baker checked the bread's freshness before opening the shop.","example_zh":"麵包師開店前檢查麵包的新鮮度。","original_meaning":"新鮮度","original_example":"The chef checks the freshness of the fish when it arrives each morning.","original_example_zh":"魚每天早上送達時，廚師都會檢查新鮮度。"},{"source_id":6407,"word":"agriculture","meaning":"農業","example":"The museum explored the history of agriculture in the valley.","example_zh":"博物館探討山谷農業的歷史。","original_meaning":"農業","original_example":"The documentary showed how changing rainfall affects local agriculture.","original_example_zh":"紀錄片呈現降雨變化如何影響當地農業。"},{"source_id":6408,"word":"transportation","meaning":"交通運輸","example":"The city improved transportation by adding new bus routes.","example_zh":"城市透過增加公車路線改善交通運輸。","original_meaning":"交通運輸","original_example":"The school arranged transportation for students joining the beach cleanup.","original_example_zh":"學校為參加淨灘的學生安排交通。"},{"source_id":6409,"word":"public transit","meaning":"大眾運輸","example":"Using public transit made the trip to the museum easier.","example_zh":"搭乘大眾運輸讓前往博物館更方便。","original_meaning":"大眾運輸","original_example":"Using public transit saved us the trouble of finding parking downtown.","original_example_zh":"搭乘大眾運輸省去了在市中心找停車位的麻煩。"},{"source_id":6413,"word":"lane","meaning":"車道；小路","example":"The cyclist stayed in the marked bicycle lane.","example_zh":"騎士保持在標示清楚的自行車道內。","original_meaning":"車道；小路","original_example":"A delivery truck blocked the bike lane, so we slowed down.","original_example_zh":"一輛送貨卡車擋住自行車道，所以我們放慢速度。"},{"source_id":6414,"word":"highway","meaning":"公路；高速公路","example":"The highway curved around the mountain.","example_zh":"公路沿著山勢彎曲。","original_meaning":"公路；高速公路","original_example":"We left before sunrise to avoid holiday traffic on the highway.","original_example_zh":"我們在日出前出發，以避開高速公路的假日車潮。"},{"source_id":6415,"word":"subway","meaning":"地下鐵；地鐵","example":"They took the subway to the city center.","example_zh":"他們搭地鐵前往市中心。","original_meaning":"地下鐵；地鐵","original_example":"The subway remained crowded even after the evening rush hour.","original_example_zh":"即使晚間尖峰時間過後，地鐵仍然很擁擠。"},{"source_id":6416,"word":"commuter","meaning":"通勤者","example":"The commuter read a book on the morning train.","example_zh":"通勤者在早班火車上看書。","original_meaning":"通勤者","original_example":"Many commuters read or listen to podcasts on the morning train.","original_example_zh":"許多通勤者會在早班火車上閱讀或聽 Podcast。"},{"source_id":6417,"word":"automobile","meaning":"汽車","example":"The museum displayed an early automobile.","example_zh":"博物館展示一輛早期汽車。","original_meaning":"汽車","original_example":"The museum displays an early automobile beside a modern electric car.","original_example_zh":"博物館把早期汽車和現代電動車並列展示。"},{"source_id":6418,"word":"fuel","meaning":"燃料","example":"The driver checked the fuel level before the trip.","example_zh":"駕駛出發前檢查燃料存量。","original_meaning":"燃料","original_example":"Dad compares fuel prices before a long drive south.","original_example_zh":"爸爸長途開車南下前會比較燃油價格。"},{"source_id":6419,"word":"electric vehicle","meaning":"電動車","example":"The electric vehicle charged beside the library.","example_zh":"這輛電動車在圖書館旁充電。","original_meaning":"電動車","original_example":"Our apartment installed two charging spaces for electric vehicles.","original_example_zh":"我們的公寓設置了兩個電動車充電車位。"},{"source_id":6421,"word":"navigation","meaning":"導航；航行","example":"The sailor used a map to practice navigation.","example_zh":"水手用地圖練習航行定位。","original_meaning":"導航；航行","original_example":"The navigation app suggested another road after an accident blocked the bridge.","original_example_zh":"橋上事故造成封路後，導航應用程式建議改走另一條路。"},{"source_id":6424,"word":"delay","meaning":"延誤；耽擱","example":"A signal problem caused a short delay.","example_zh":"號誌問題造成短暫延誤。","original_meaning":"延誤；耽擱","original_example":"The airline sent a message explaining the two-hour delay.","original_example_zh":"航空公司傳訊息說明班機延誤兩小時的原因。"},{"source_id":6425,"word":"fare","meaning":"票價；車費","example":"The passenger checked the bus fare before boarding.","example_zh":"乘客上車前先確認公車票價。","original_meaning":"票價；車費","original_example":"Students can use a special card to pay a lower bus fare.","original_example_zh":"學生可以使用專用卡支付較低的公車票價。"},{"source_id":6426,"word":"luggage","meaning":"行李","example":"They placed their luggage on the hotel cart.","example_zh":"他們把行李放在旅館推車上。","original_meaning":"行李","original_example":"I tied a bright ribbon to my luggage so I could recognize it quickly.","original_example_zh":"我在行李上綁了鮮豔緞帶，方便快速辨認。"},{"source_id":6427,"word":"board","meaning":"登上；董事會；木板","example":"The passengers waited for their turn to board the ferry.","example_zh":"乘客等候依序登上渡輪。","original_meaning":"登上；董事會；木板","original_example":"Passengers began to board the ferry twenty minutes before departure.","original_example_zh":"乘客在出發前二十分鐘開始登船。"},{"source_id":6430,"word":"colleague","meaning":"同事","example":"Her colleague helped prepare the classroom display.","example_zh":"她的同事協助布置教室展示。","original_meaning":"同事","original_example":"Mom and her colleague took turns covering the front desk during lunch.","original_example_zh":"媽媽和同事午餐時間輪流顧櫃檯。"},{"source_id":6431,"word":"sibling","meaning":"兄弟姊妹","example":"Each sibling chose a different book for the trip.","example_zh":"兄弟姊妹各自為旅程挑了不同的書。","original_meaning":"兄弟姊妹","original_example":"My sibling and I share a desk, so we keep separate drawers.","original_example_zh":"我和手足共用一張書桌，所以各自使用不同抽屜。"},{"source_id":6432,"word":"adolescent","meaning":"青少年；青春期的","example":"The program helped each adolescent explore new interests.","example_zh":"這項計畫幫助每位青少年探索新興趣。","original_meaning":"青少年；青春期的","original_example":"The workshop teaches adolescents how to handle online pressure.","original_example_zh":"這場工作坊教青少年如何面對網路壓力。"},{"source_id":6434,"word":"citizen","meaning":"公民；市民","example":"Every citizen was invited to the town meeting.","example_zh":"每位公民都受邀參加鎮民大會。","original_meaning":"公民；市民","original_example":"Citizens reported the broken streetlight through the city app.","original_example_zh":"市民透過市政應用程式通報故障的路燈。"},{"source_id":6435,"word":"resident","meaning":"居民；住院醫師","example":"The resident planted flowers outside her apartment.","example_zh":"這位居民在公寓外種花。","original_meaning":"居民；住院醫師","original_example":"Local residents asked for a safer crossing near the elementary school.","original_example_zh":"當地居民要求在小學附近增設更安全的過街設施。"},{"source_id":6437,"word":"employer","meaning":"雇主","example":"The employer explained the training program to the new staff.","example_zh":"雇主向新員工說明培訓計畫。","original_meaning":"雇主","original_example":"The employer explained the weekend schedule before my brother accepted the job.","original_example_zh":"哥哥接受工作前，雇主先說明了週末的班表。"},{"source_id":6439,"word":"supervisor","meaning":"主管；督導","example":"The supervisor checked the model before the exhibition opened.","example_zh":"主管在展覽開幕前檢查模型。","original_meaning":"主管；督導","original_example":"My supervisor showed me how to lock the shop before I worked the closing shift alone.","original_example_zh":"我第一次獨自上晚班前，主管教我如何鎖好店門。"},{"source_id":6440,"word":"consumer","meaning":"消費者","example":"The consumer compared two reusable water bottles.","example_zh":"消費者比較了兩款可重複使用的水瓶。","original_meaning":"消費者","original_example":"A careful consumer compares repair costs before replacing a broken phone.","original_example_zh":"謹慎的消費者會先比較維修費，再決定是否換掉壞手機。"},{"source_id":6441,"word":"roommate","meaning":"室友","example":"Her roommate helped carry the boxes upstairs.","example_zh":"室友幫忙把箱子搬上樓。","original_meaning":"室友","original_example":"My roommate leaves for work early, so she prepares breakfast without using the blender.","original_example_zh":"室友很早上班，所以她準備早餐時不使用果汁機。"},{"source_id":6444,"word":"conservation","meaning":"保育；節約","example":"The class joined a project for wetland conservation.","example_zh":"全班加入濕地保育計畫。","original_meaning":"保育；節約","original_example":"The zoo uses ticket income to support wildlife conservation.","original_example_zh":"動物園把門票收入用於支持野生動物保育。"},{"source_id":6445,"word":"renewable","meaning":"可再生的","example":"The students built a model powered by renewable energy.","example_zh":"學生製作以再生能源供電的模型。","original_meaning":"可再生的","original_example":"The new sports center gets part of its power from renewable energy.","original_example_zh":"新的運動中心有部分電力來自再生能源。"},{"source_id":6447,"word":"atmosphere","meaning":"大氣；氣氛","example":"The model showed the atmosphere surrounding Earth.","example_zh":"模型展示環繞地球的大氣層。","original_meaning":"大氣；氣氛","original_example":"Smoke from the fire remained in the atmosphere for several days.","original_example_zh":"火災產生的煙霧在大氣中停留了好幾天。"},{"source_id":6448,"word":"endangered","meaning":"瀕危的","example":"The exhibit introduced several endangered animals.","example_zh":"展覽介紹幾種瀕危動物。","original_meaning":"瀕危的","original_example":"The rescue center cares for endangered turtles injured by fishing nets.","original_example_zh":"救援中心照顧被漁網弄傷的瀕危海龜。"},{"source_id":6453,"word":"ecological","meaning":"生態的","example":"The team studied the river's ecological importance.","example_zh":"團隊研究這條河的生態重要性。","original_meaning":"生態的","original_example":"The guide explained the ecological value of leaving fallen trees in the forest.","original_example_zh":"導覽員解釋把倒木留在森林裡的生態價值。"},{"source_id":6454,"word":"coastal","meaning":"沿海的；海岸的","example":"The coastal path offered views of the harbor.","example_zh":"沿海步道可以眺望港口。","original_meaning":"沿海的；海岸的","original_example":"A coastal village moved its market indoors when strong winds arrived.","original_example_zh":"強風來襲時，一座沿海村莊把市集移到室內。"},{"source_id":6455,"word":"climate change","meaning":"氣候變遷","example":"The lecture explored evidence of climate change.","example_zh":"講座探討氣候變遷的證據。","original_meaning":"氣候變遷","original_example":"Our family chose a drought-tolerant garden after summers became hotter because of climate change.","original_example_zh":"因氣候變遷讓夏天越來越熱，我們家改種耐旱的庭園植物。"},{"source_id":6456,"word":"profit","meaning":"利潤；獲利","example":"The shop used part of its profit to improve the garden.","example_zh":"商店用部分利潤改善花園。","original_meaning":"利潤；獲利","original_example":"The student-run café donated its profit after paying for ingredients.","original_example_zh":"學生經營的咖啡店扣除食材成本後，把利潤捐了出去。"},{"source_id":6458,"word":"contract","meaning":"合約；契約","example":"Both sides read the contract before signing it.","example_zh":"雙方在簽署前先閱讀合約。","original_meaning":"合約；契約","original_example":"My brother read the phone contract carefully before signing it.","original_example_zh":"哥哥在簽手機合約前仔細閱讀內容。"},{"source_id":6459,"word":"salary","meaning":"薪資","example":"She planned her monthly budget after receiving her salary.","example_zh":"她領到薪資後規畫每月預算。","original_meaning":"薪資","original_example":"The job posting lists the salary, work hours, and required experience.","original_example_zh":"徵才公告列出了薪資、工時與所需經驗。"},{"source_id":6460,"word":"negotiate","meaning":"協商；談判","example":"The neighbors met to negotiate a fair use of the shared garden.","example_zh":"鄰居見面協商如何公平使用共用花園。","original_meaning":"協商；談判","original_example":"The club negotiated a lower price for printing two hundred T-shirts.","original_example_zh":"社團為印製兩百件 T 恤協商到較低價格。"},{"source_id":226,"word":"allocate","meaning":"分配","example":"The teacher will allocate a shelf to each group.","example_zh":"老師會分配一層架子給每組。","original_meaning":"分配","original_example":"Resources were allocated fairly.","original_example_zh":"資源分配公平。"},{"source_id":229,"word":"anonymous","meaning":"匿名的","example":"An anonymous donor paid for the new library shelves.","example_zh":"一位匿名捐款者支付了新書架的費用。","original_meaning":"匿名的","original_example":"The donor remained anonymous.","original_example_zh":"捐贈者保持匿名。"},{"source_id":237,"word":"bureaucracy","meaning":"官僚體制","example":"The guide helped visitors understand the permit bureaucracy.","example_zh":"指南協助訪客了解許可申請的官僚程序。","original_meaning":"官僚體制","original_example":"The bureaucracy slows things down.","original_example_zh":"官僚體制拖慢了進度。"},{"source_id":238,"word":"catastrophe","meaning":"大災難","example":"The museum documented a natural catastrophe from the town's past.","example_zh":"博物館記錄了鎮上過去的一場自然災難。","original_meaning":"大災難","original_example":"The earthquake was a catastrophe.","original_example_zh":"那場地震是一場災難。"},{"source_id":245,"word":"consecutive","meaning":"連續的","example":"The team won three consecutive matches.","example_zh":"這支隊伍連續贏了三場比賽。","original_meaning":"連續的","original_example":"He won three consecutive games.","original_example_zh":"他連贏三場比賽。"},{"source_id":248,"word":"constitute","meaning":"構成","example":"These small islands constitute a single nature reserve.","example_zh":"這些小島共同構成一個自然保護區。","original_meaning":"構成","original_example":"Women constitute 50% of the population.","original_example_zh":"女性佔人口的50%。"},{"source_id":251,"word":"correlation","meaning":"相關性","example":"The students found a correlation between sunlight and plant growth.","example_zh":"學生發現日照與植物生長有相關性。","original_meaning":"相關性","original_example":"There is a strong correlation.","original_example_zh":"兩者之間存在高度相關性。"},{"source_id":260,"word":"disproportionate","meaning":"不成比例的","example":"The tiny bridge received a disproportionate amount of attention.","example_zh":"這座小橋受到的關注與其規模不成比例。","original_meaning":"不成比例的","original_example":"A disproportionate response.","original_example_zh":"反應過度。"},{"source_id":268,"word":"erode","meaning":"侵蝕","example":"Waves slowly erode the soft rock along the shore.","example_zh":"海浪逐漸侵蝕岸邊柔軟岩石。","original_meaning":"侵蝕","original_example":"The coast is being eroded.","original_example_zh":"海岸正遭受侵蝕。"},{"source_id":273,"word":"fluctuate","meaning":"波動","example":"The river's water level can fluctuate throughout the year.","example_zh":"河川水位全年可能起伏變動。","original_meaning":"波動","original_example":"Prices fluctuate daily.","original_example_zh":"價格每日波動。"},{"source_id":277,"word":"hierarchy","meaning":"階層","example":"The diagram showed the library's management hierarchy.","example_zh":"圖表顯示圖書館的管理階層。","original_meaning":"階層","original_example":"The company hierarchy.","original_example_zh":"公司的階層結構。"},{"source_id":279,"word":"ideology","meaning":"意識形態","example":"The students compared the ideology of two fictional societies.","example_zh":"學生比較兩個虛構社會的意識形態。","original_meaning":"意識形態","original_example":"Their political ideology shaped their decisions about how society should work.","original_example_zh":"他們的政治理念形塑了他們對社會運作方式的決策。"},{"source_id":284,"word":"indigenous","meaning":"原住民的","example":"The center displayed work by indigenous artists.","example_zh":"中心展示原住民藝術家的作品。","original_meaning":"原住民的","original_example":"The museum displayed beautiful artwork made by indigenous people.","original_example_zh":"博物館展出了原住民創作的精美藝術品。"},{"source_id":286,"word":"infrastructure","meaning":"基礎設施","example":"The town improved its infrastructure with new water pipes.","example_zh":"鎮上鋪設新水管，改善基礎設施。","original_meaning":"基礎設施","original_example":"Good roads are an important part of a country's infrastructure.","original_example_zh":"良好的道路是國家基礎建設的重要組成部分。"},{"source_id":289,"word":"integrity","meaning":"正直","example":"The librarian showed integrity by returning the lost money.","example_zh":"館員歸還失款，展現正直。","original_meaning":"正直","original_example":"A person of integrity.","original_example_zh":"一位正直的人。"},{"source_id":293,"word":"pragmatic","meaning":"務實的","example":"The team chose a pragmatic plan that used materials already available.","example_zh":"團隊選擇務實計畫，使用現有材料。","original_meaning":"務實的","original_example":"A pragmatic approach.","original_example_zh":"務實的做法。"},{"source_id":294,"word":"predominant","meaning":"主要的","example":"Green was the predominant color in the painting.","example_zh":"綠色是這幅畫的主色。","original_meaning":"主要的","original_example":"The predominant opinion.","original_example_zh":"主流意見。"},{"source_id":296,"word":"resilient","meaning":"有韌性的","example":"The resilient town rebuilt its library after the storm.","example_zh":"這座有韌性的城鎮在風暴後重建圖書館。","original_meaning":"有韌性的","original_example":"Children are resilient.","original_example_zh":"孩子們很有韌性。"},{"source_id":297,"word":"rhetoric","meaning":"修辭","example":"The class analyzed the speaker's use of rhetoric.","example_zh":"全班分析演講者運用的修辭。","original_meaning":"修辭","original_example":"The politician's smooth rhetoric convinced many voters, even though his ideas were weak.","original_example_zh":"儘管這位政治家的理念薄弱，但他流暢的演說仍說服了許多選民。"},{"source_id":301,"word":"sovereignty","meaning":"主權","example":"The history book discussed the island's struggle for sovereignty.","example_zh":"歷史書討論這座島爭取主權的歷程。","original_meaning":"主權","original_example":"Every country has the right to defend its sovereignty and borders.","original_example_zh":"每個國家都有權捍衛其主權與邊界。"},{"source_id":306,"word":"tentative","meaning":"暫定的","example":"The group made a tentative plan for the field trip.","example_zh":"小組為實地考察擬定暫定計畫。","original_meaning":"暫定的","original_example":"A tentative plan.","original_example_zh":"初步的計畫。"},{"source_id":308,"word":"unanimous","meaning":"一致的","example":"The committee reached a unanimous decision to protect the garden.","example_zh":"委員會一致決定保護花園。","original_meaning":"一致的","original_example":"A unanimous decision.","original_example_zh":"一致通過的決定。"},{"source_id":751,"word":"acquisition","meaning":"獲得","example":"The museum celebrated the acquisition of a rare map.","example_zh":"博物館慶祝獲得一幅珍稀地圖。","original_meaning":"獲得","original_example":"The company's recent acquisition of a smaller firm will help it grow.","original_example_zh":"該公司最近收購了一家較小的公司，這將有助於其成長。"},{"source_id":752,"word":"adjacent","meaning":"鄰近的","example":"The library is adjacent to the community garden.","example_zh":"圖書館緊鄰社區花園。","original_meaning":"鄰近的","original_example":"The adjacent room.","original_example_zh":"隔壁房間。"},{"source_id":755,"word":"aesthetic","meaning":"美學的","example":"The architect considered the building's aesthetic appeal.","example_zh":"建築師考量建築在美學上的吸引力。","original_meaning":"美學的","original_example":"The artist focused on the aesthetic appeal of the sculpture.","original_example_zh":"這位藝術家著重雕塑的美學魅力。"},{"source_id":756,"word":"aggregate","meaning":"總計的","example":"The report compared the aggregate cost of the two plans.","example_zh":"報告比較兩項計畫的總成本。","original_meaning":"總計的","original_example":"The aggregate score.","original_example_zh":"總分。"},{"source_id":757,"word":"allegation","meaning":"指控","example":"The committee examined the allegation before reaching a conclusion.","example_zh":"委員會在下結論前先調查指控。","original_meaning":"指控","original_example":"The police are investigating the serious allegation of fraud.","original_example_zh":"警方正在調查這項嚴重的詐欺指控。"},{"source_id":761,"word":"analogy","meaning":"類比","example":"The teacher used a bridge as an analogy for communication.","example_zh":"老師把橋梁當作溝通的類比。","original_meaning":"類比","original_example":"Draw an analogy.","original_example_zh":"進行類比。"},{"source_id":762,"word":"apparatus","meaning":"裝置","example":"The students checked the apparatus before the experiment.","example_zh":"學生在實驗前檢查裝置。","original_meaning":"裝置","original_example":"The scientist carefully assembled the complex laboratory apparatus for the experiment.","original_example_zh":"那位科學家仔細地組裝了實驗所需的複雜儀器。"},{"source_id":764,"word":"arbitrary","meaning":"武斷的","example":"The students questioned the arbitrary choice of team colors.","example_zh":"學生質疑隊伍顏色的武斷選擇。","original_meaning":"武斷的","original_example":"An arbitrary decision.","original_example_zh":"武斷的決定。"},{"source_id":769,"word":"autonomous","meaning":"自主的","example":"The autonomous robot followed a marked route.","example_zh":"自主機器人沿標示路線行進。","original_meaning":"自主的","original_example":"An autonomous vehicle.","original_example_zh":"一輛自動駕駛車。"},{"source_id":770,"word":"avert","meaning":"避免","example":"The quick repair helped avert a larger problem.","example_zh":"迅速修理有助避免更大的問題。","original_meaning":"避免","original_example":"Avert a disaster.","original_example_zh":"避免災難。"},{"source_id":771,"word":"benign","meaning":"良性的","example":"The doctor explained that the lump was benign.","example_zh":"醫師解釋這個腫塊是良性的。","original_meaning":"良性的","original_example":"A benign tumor.","original_example_zh":"良性腫瘤。"},{"source_id":774,"word":"blaze","meaning":"燃燒","example":"A small fire began to blaze in the enclosed fireplace.","example_zh":"封閉壁爐裡的小火開始旺盛燃燒。","original_meaning":"燃燒","original_example":"The fire blazed all night.","original_example_zh":"大火整夜燃燒。"},{"source_id":776,"word":"bolster","meaning":"支撐","example":"The extra support helped bolster the bridge model.","example_zh":"額外支架有助加固橋梁模型。","original_meaning":"支撐","original_example":"Bolster the economy.","original_example_zh":"提振經濟。"},{"source_id":778,"word":"brink","meaning":"邊緣","example":"The path stopped at the brink of the old quarry.","example_zh":"步道在舊採石場邊緣盡頭停止。","original_meaning":"邊緣","original_example":"On the brink of war.","original_example_zh":"瀕臨戰爭邊緣。"},{"source_id":781,"word":"cater","meaning":"迎合","example":"The museum designed activities to cater to different interests.","example_zh":"博物館設計活動以迎合不同興趣。","original_meaning":"迎合","original_example":"Cater to customer needs.","original_example_zh":"滿足客戶需求。"},{"source_id":785,"word":"coherent","meaning":"連貫的","example":"Her report gave a coherent account of the experiment.","example_zh":"她的報告連貫地說明了實驗經過。","original_meaning":"連貫的","original_example":"A coherent argument.","original_example_zh":"一個條理分明的論點。"},{"source_id":787,"word":"commence","meaning":"開始","example":"The concert will commence after the doors close.","example_zh":"大門關閉後，音樂會將開始。","original_meaning":"開始","original_example":"The ceremony will commence.","original_example_zh":"儀式即將開始。"},{"source_id":798,"word":"conquest","meaning":"征服","example":"The historian discussed the conquest of the ancient city.","example_zh":"歷史學家討論這座古城遭征服的歷史。","original_meaning":"征服","original_example":"The conquest of space.","original_example_zh":"征服太空。"},{"source_id":801,"word":"conspiracy","meaning":"陰謀","example":"The detective uncovered a conspiracy in the novel.","example_zh":"偵探在小說中揭露了一樁陰謀。","original_meaning":"陰謀","original_example":"A conspiracy theory.","original_example_zh":"陰謀論。"},{"source_id":817,"word":"cynical","meaning":"憤世嫉俗的","example":"The cynical critic doubted the mayor's promise.","example_zh":"憤世嫉俗的評論者懷疑市長的承諾。","original_meaning":"憤世嫉俗的","original_example":"A cynical attitude.","original_example_zh":"一種玩世不恭的態度。"},{"source_id":820,"word":"degradation","meaning":"退化；劣化","example":"The scientists studied the degradation of the old plastic samples.","example_zh":"科學家研究舊塑膠樣本的劣化。","original_meaning":"退化","original_example":"Environmental degradation.","original_example_zh":"環境惡化。"},{"source_id":823,"word":"deploy","meaning":"部署","example":"The team will deploy sensors along the river.","example_zh":"團隊將沿河部署感測器。","original_meaning":"部署","original_example":"Deploy the troops.","original_example_zh":"部署部隊。"},{"source_id":828,"word":"detain","meaning":"拘留","example":"The officers had to detain the suspect while checking the evidence.","example_zh":"警員在查核證據時必須暫時拘留嫌疑人。","original_meaning":"拘留","original_example":"The police detained the suspect.","original_example_zh":"警方拘留了該名嫌犯。"},{"source_id":829,"word":"deter","meaning":"阻止","example":"The sturdy fence helped deter visitors from entering the closed area.","example_zh":"堅固圍欄有助阻止訪客進入封閉區域。","original_meaning":"阻止","original_example":"The penalty deters crime.","original_example_zh":"這項刑罰具有威懾作用。"},{"source_id":835,"word":"discourse","meaning":"論述","example":"The seminar encouraged thoughtful discourse about education.","example_zh":"研討會鼓勵對教育進行深思熟慮的論述。","original_meaning":"論述","original_example":"Academic discourse.","original_example_zh":"學術論述。"},{"source_id":844,"word":"doctrine","meaning":"教義","example":"The historian explained a religious doctrine from the ancient text.","example_zh":"歷史學家解釋古文獻中的一項宗教教義。","original_meaning":"教義","original_example":"Political doctrine.","original_example_zh":"政治學說。"},{"source_id":847,"word":"doom","meaning":"厄運","example":"The story's hero feared that the warning foretold doom.","example_zh":"故事主角擔心這則警告預示厄運。","original_meaning":"厄運","original_example":"A sense of doom.","original_example_zh":"一種末日感。"},{"source_id":856,"word":"empirical","meaning":"實證的","example":"The students supported their claim with empirical evidence.","example_zh":"學生以實證資料支持主張。","original_meaning":"實證的","original_example":"Empirical evidence.","original_example_zh":"實證。"}]$senior_content$::jsonb; begin
perform 1 from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' for update of w;
if (select count(*) from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' and ((w.meaning,w.example,w.example_zh) is not distinct from (c.original_meaning,c.original_example,c.original_example_zh) or (w.meaning,w.example,w.example_zh) is not distinct from (c.meaning,c.example,c.example_zh))) <> 100 then raise exception 'Senior source rows changed; refusing overwrite'; end if;
update public.word_bank w set meaning=c.meaning,example=c.example,example_zh=c.example_zh from jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) where w.id=c.source_id and w.level='senior' and w.word=c.word;
end $guard$;
insert into public.word_illustrations(id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version) select id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version from jsonb_to_recordset($senior_rows$[{"id":"senior-academic-01-v1","level":"senior","word":"academic","sort_order":1,"sense":"學業的；學術的","alt_zh":"高中生在圖書館桌上攤開歷史書與生物學模型筆記。","example":"Her academic interests included history and biology.","example_zh":"她的學術興趣包括歷史與生物。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/academic-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-lecture-01-v1","level":"senior","word":"lecture","sort_order":1,"sense":"講座；演講","alt_zh":"成年講師在禮堂古城模型旁講解，學生聆聽。","example":"The students attended a lecture about ancient cities.","example_zh":"學生參加一場關於古城的講座。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/lecture-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-nutritious-01-v1","level":"senior","word":"nutritious","sort_order":1,"sense":"營養豐富的","alt_zh":"成年廚師端出有多種蔬菜、穀物與豆類的色彩豐富午餐。","example":"The cook prepared a nutritious lunch for the group.","example_zh":"廚師為團體準備營養豐富的午餐。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/nutritious-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-balanced-01-v1","level":"senior","word":"balanced","sort_order":1,"sense":"均衡的；平衡的","alt_zh":"學校餐盤整齊擺放蔬菜、水果、穀物與蛋白質食物。","example":"The cafeteria offered a balanced meal with several food groups.","example_zh":"餐廳提供包含多類食物的均衡餐點。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/balanced-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-consume-01-v1","level":"senior","word":"consume","sort_order":1,"sense":"食用；消耗","alt_zh":"成年健行者在安全休息亭打開午餐盒準備用餐。","example":"The hikers planned to consume their packed lunch at the rest stop.","example_zh":"健行者計畫在休息站吃帶來的午餐。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/consume-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-dietary-01-v1","level":"senior","word":"dietary","sort_order":1,"sense":"飲食的","alt_zh":"成年主廚在餐廳和成年顧客討論菜單，桌上多樣菜餚圖片。","example":"The chef asked about the guests' dietary preferences.","example_zh":"主廚詢問客人的飲食偏好。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/dietary-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-serving-01-v1","level":"senior","word":"serving","sort_order":1,"sense":"一份食物；服務","alt_zh":"成年廚師在整齊碗中分盛同量蔬菜湯。","example":"She placed a serving of soup in each bowl.","example_zh":"她在每個碗裡盛了一份湯。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/serving-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-processed-01-v1","level":"senior","word":"processed","sort_order":1,"sense":"加工的","alt_zh":"料理教室桌上一邊新鮮蔬果，一邊麵包罐頭等加工食品，教師講解，無好壞標籤。","example":"The lesson compared fresh ingredients with processed foods.","example_zh":"課程比較新鮮食材與加工食品。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/processed-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-preserve-01-v1","level":"senior","word":"preserve","sort_order":1,"sense":"保存；保護","alt_zh":"成年典藏人員戴手套將老照片放入保護套與檔案盒。","example":"The museum worked to preserve the old photographs.","example_zh":"博物館努力保存這些老照片。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/preserve-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-calorie-01-v1","level":"senior","word":"calorie","sort_order":1,"sense":"卡路里；熱量","alt_zh":"成年營養師在桌上幾種點心旁查看包裝營養表，無建議攝取量或數字特寫。","example":"The dietitian compared the calorie content of several snacks.","example_zh":"營養師比較了幾種點心的熱量。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/calorie-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-carbohydrate-01-v1","level":"senior","word":"carbohydrate","sort_order":1,"sense":"碳水化合物","alt_zh":"健康教室桌上穀物麵包米飯與抽象分子模型，教師講解。","example":"The class studied carbohydrate as one component of food.","example_zh":"全班把碳水化合物作為食物的一種成分來研究。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/carbohydrate-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-vitamin-01-v1","level":"senior","word":"vitamin","sort_order":1,"sense":"維生素","alt_zh":"圖書館食品科學書旁有多樣水果蔬菜與簡單分子教具，無補充藥丸。","example":"The food science book included a chapter about each vitamin.","example_zh":"食品科學書有專章介紹每一種維生素。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/vitamin-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-vegetarian-01-v1","level":"senior","word":"vegetarian","sort_order":1,"sense":"素食者；素食的","alt_zh":"成年餐廳客人微笑選擇豆類蔬菜料理，桌上菜單。","example":"The vegetarian chose a dish made with beans and vegetables.","example_zh":"這位素食者選了一道以豆類和蔬菜做成的料理。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/vegetarian-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-fermented-01-v1","level":"senior","word":"fermented","sort_order":1,"sense":"發酵的","alt_zh":"成年廚師用乾淨夾子從玻璃罐取發酵高麗菜放小碟。","example":"The cook added fermented cabbage to the meal.","example_zh":"廚師在餐點裡加上發酵高麗菜。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/fermented-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-freshness-01-v1","level":"senior","word":"freshness","sort_order":1,"sense":"新鮮度","alt_zh":"成年麵包師在明亮店內檢查剛烤好的金黃麵包。","example":"The baker checked the bread's freshness before opening the shop.","example_zh":"麵包師開店前檢查麵包的新鮮度。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/freshness-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-agriculture-01-v1","level":"senior","word":"agriculture","sort_order":1,"sense":"農業","alt_zh":"博物館桌上山谷農田模型與傳統農具靜態展示。","example":"The museum explored the history of agriculture in the valley.","example_zh":"博物館探討山谷農業的歷史。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/agriculture-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-transportation-01-v1","level":"senior","word":"transportation","sort_order":1,"sense":"交通運輸","alt_zh":"城市模型中公車沿新路線連接住宅與學校，成年規畫師講解。","example":"The city improved transportation by adding new bus routes.","example_zh":"城市透過增加公車路線改善交通運輸。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/transportation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-public transit-01-v1","level":"senior","word":"public transit","sort_order":1,"sense":"大眾運輸","alt_zh":"成年旅客從城市公車下車走向近處博物館，旁有地鐵入口。","example":"Using public transit made the trip to the museum easier.","example_zh":"搭乘大眾運輸讓前往博物館更方便。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/public%20transit-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-lane-01-v1","level":"senior","word":"lane","sort_order":1,"sense":"車道；小路","alt_zh":"成年騎士戴安全帽在與車流隔離的自行車道行進。","example":"The cyclist stayed in the marked bicycle lane.","example_zh":"騎士保持在標示清楚的自行車道內。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/lane-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-highway-01-v1","level":"senior","word":"highway","sort_order":1,"sense":"公路；高速公路","alt_zh":"寬闊山區公路平順繞山，少量車輛有序行駛。","example":"The highway curved around the mountain.","example_zh":"公路沿著山勢彎曲。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/highway-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-subway-01-v1","level":"senior","word":"subway","sort_order":1,"sense":"地下鐵；地鐵","alt_zh":"成年旅客在明亮地鐵車廂內坐著，透窗看地下站台。","example":"They took the subway to the city center.","example_zh":"他們搭地鐵前往市中心。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/subway-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-commuter-01-v1","level":"senior","word":"commuter","sort_order":1,"sense":"通勤者","alt_zh":"成年上班族坐在通勤列車靠窗位置閱讀，早晨城市窗景。","example":"The commuter read a book on the morning train.","example_zh":"通勤者在早班火車上看書。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/commuter-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-automobile-01-v1","level":"senior","word":"automobile","sort_order":1,"sense":"汽車","alt_zh":"交通博物館展示古老汽車，成年訪客在圍欄外欣賞。","example":"The museum displayed an early automobile.","example_zh":"博物館展示一輛早期汽車。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/automobile-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-fuel-01-v1","level":"senior","word":"fuel","sort_order":1,"sense":"燃料","alt_zh":"停妥汽車內成年駕駛查看儀表板燃料指針，無品牌。","example":"The driver checked the fuel level before the trip.","example_zh":"駕駛出發前檢查燃料存量。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/fuel-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-electric vehicle-01-v1","level":"senior","word":"electric vehicle","sort_order":1,"sense":"電動車","alt_zh":"停妥電動汽車連接圖書館旁充電樁，日光清楚，無品牌。","example":"The electric vehicle charged beside the library.","example_zh":"這輛電動車在圖書館旁充電。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/electric%20vehicle-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-navigation-01-v1","level":"senior","word":"navigation","sort_order":1,"sense":"導航；航行","alt_zh":"成年水手在岸邊教室桌上研究海圖與羅盤，無風險海況。","example":"The sailor used a map to practice navigation.","example_zh":"水手用地圖練習航行定位。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/navigation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-delay-01-v1","level":"senior","word":"delay","sort_order":1,"sense":"延誤；耽擱","alt_zh":"火車站成年旅客耐心在月台安全線後等待，鐵路人員查看訊號設備。","example":"A signal problem caused a short delay.","example_zh":"號誌問題造成短暫延誤。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/delay-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-fare-01-v1","level":"senior","word":"fare","sort_order":1,"sense":"票價；車費","alt_zh":"成年乘客在公車站查看票價資訊板，手拿交通卡，無可讀字。","example":"The passenger checked the bus fare before boarding.","example_zh":"乘客上車前先確認公車票價。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/fare-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-luggage-01-v1","level":"senior","word":"luggage","sort_order":1,"sense":"行李","alt_zh":"成年旅客在旅館大廳將行李箱放穩四輪行李推車。","example":"They placed th